// WebcamJS v1.0.26 - Webcam Library for HTML5/WebRTC
(function(window) {
	var _user_options = {
		width: 320,
		height: 240,
		dest_width: 0,
		dest_height: 0,
		image_format: 'jpeg',
		jpeg_quality: 90,
		enable_cors: 0,
		force_flash: 0,
		flip_horiz: 0,
		fps: 30,
		upload_name: 'webcam',
		constraints: null,
		swfURL: '',
		loseless: 0,
		auth_token: null,
		callback_url: null
	};
	var _params = {};
	var _container = null;
	var _webcam = null;
	var _stream = null;
	var _video = null;
	var _canvas = null;
	var _context = null;
	var Webcam = {
		version: '1.0.26',
		config: function(options) {
			for (var key in options) {
				_user_options[key] = options[key];
			}
		},
		set: function(key, value) {
			if (typeof key === 'object') {
				for (var k in key) {
					_user_options[k] = key[k];
				}
			} else {
				_user_options[key] = value;
			}
		},
		on: function(name, callback) {
			_params[name] = callback;
		},
		off: function(name) {
			delete _params[name];
		},
		dispatch: function(name, args) {
			if (_params[name]) {
				_params[name].apply(this, args);
			}
		},
		attach: function(elem) {
			if (typeof elem === 'string') {
				elem = document.getElementById(elem);
			}
			_container = elem;
			_container.innerHTML = '';
			
			_video = document.createElement('video');
			_video.setAttribute('autoplay', '');
			_video.setAttribute('playsinline', '');
			_video.style.width = _user_options.width + 'px';
			_video.style.height = _user_options.height + 'px';
			_container.appendChild(_video);

			var constraints = _user_options.constraints || {
				video: {
					width: { ideal: _user_options.dest_width || _user_options.width },
					height: { ideal: _user_options.dest_height || _user_options.height },
					facingMode: 'user'
				}
			};
			if (typeof constraints.video === 'boolean') {
				constraints.video = {};
			}
			constraints.video = Object.assign({
				width: { ideal: _user_options.dest_width || _user_options.width },
				height: { ideal: _user_options.dest_height || _user_options.height },
				facingMode: 'user'
			}, constraints.video || {});

			if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
				Webcam.dispatch('error', [new Error('Browser ini tidak mendukung getUserMedia untuk kamera.')]);
				return;
			}

			navigator.mediaDevices.getUserMedia(constraints).then(function(stream) {
				_stream = stream;
				_video.srcObject = stream;
				_video.play();
				Webcam.dispatch('live', []);
			}).catch(function(err) {
				Webcam.dispatch('error', [err]);
			});
		},
		reset: function() {
			if (_stream) {
				var tracks = _stream.getTracks();
				for (var i = 0, len = tracks.length; i < len; i++) {
					tracks[i].stop();
				}
				_stream = null;
			}
			if (_container) {
				_container.innerHTML = '';
				_container = null;
			}
		},
		snap: function(callback, context) {
			if (!_video) return;
			var dest_width = _user_options.dest_width || _user_options.width;
			var dest_height = _user_options.dest_height || _user_options.height;
			
			_canvas = document.createElement('canvas');
			_canvas.width = dest_width;
			_canvas.height = dest_height;
			_context = _canvas.getContext('2d');
			
			if (_user_options.flip_horiz) {
				_context.translate(dest_width, 0);
				_context.scale(-1, 1);
			}
			
			_context.drawImage(_video, 0, 0, dest_width, dest_height);
			
			var image_format = _user_options.image_format || 'jpeg';
			var jpeg_quality = (_user_options.jpeg_quality || 90) / 100;
			var data_uri = _canvas.toDataURL('image/' + image_format, jpeg_quality);
			
			if (callback) {
				callback.call(context || this, data_uri, _canvas, _context);
			}
			return data_uri;
		}
	};
	window.Webcam = Webcam;
})(window);